<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import type { Context, Role, Scenario } from './dashboard';
import { tenantOptions } from './catalog';
import { products, defaultAccessConfig, modelIdentifierError, type AccessConfig, type Conversion, type DataType, type DpRule, type Product, type ProductInput, type ProductStatus, type ThingModelItem } from './products';
import './dashboard.css';
import './products.css';
import { downloadProductCsv } from './product-export';
import { parseJsonObject } from './model-json';
import { devices, type Device } from './devices';
import { tenants } from './tenants';

type Tab = 'basic' | 'access' | 'model' | 'dp' | 'devices';
type ListFilters = { tenantId: string; keyword: string; category: string; status: string; page: number; pageSize: number };
const tenantNames: Record<string, string> = { all: '全部租户', ...Object.fromEntries(tenantOptions().map(item => [item.id, item.name])) };
const statusNames: Record<string, string> = { draft: '草稿', published: '已发布', disabled: '已停用' };
const deviceStatusNames: Record<string, string> = { unactivated: '未激活', online: '在线', offline: '离线', fault: '故障', maintenance: '维护' };
const kindNames: Record<string, string> = { property: '属性', event: '事件', service: '服务' };
const accessNames: Record<string, string> = { read: '只读', write: '只写', readWrite: '读写' };
const tabs: { id: Tab; name: string }[] = [{ id: 'basic', name: '基础信息' }, { id: 'access', name: '接入配置' }, { id: 'model', name: '物模型' }, { id: 'dp', name: 'DP 规则' }, { id: 'devices', name: '设备' }];
const initialList = (): ListFilters => ({ tenantId: new URLSearchParams(location.search).get('tenant') || localStorage.getItem('iot-atlas-current-tenant-v1') || 'all', keyword: '', category: '', status: '', page: 1, pageSize: 10 });
const emptyProduct = (tenantId: string): ProductInput => ({ tenantId: tenantId === 'all' ? 'ten_202609_001' : tenantId, name: '', productKey: '', category: '工业传感器', protocol: 'MQTT', status: 'draft' });
const productInput = (product: Product): ProductInput => ({ tenantId: product.tenantId, name: product.name, productKey: product.productKey, category: product.category, protocol: product.protocol, status: product.status });
const emptyItem = (): ThingModelItem => ({ id: '', kind: 'property', identifier: '', name: '', dataType: 'float', accessMode: 'read', unit: '', min: 0, max: 100 });
const emptyRule = (itemId: string): DpRule => ({ id: '', itemId, rawType: 'int16', scale: 1, offset: 0, precision: 1, enumMap: [], expression: 'x' });
const number = (value: number) => new Intl.NumberFormat('zh-CN').format(value);
const copy = <T>(value: T): T => JSON.parse(JSON.stringify(value));
const role = ref<Role>('platformAdmin'), scenario = ref<Scenario>('normal');
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark');
const media = matchMedia('(prefers-color-scheme: dark)');
const systemDark = ref(media.matches);
const updateSystem = () => { systemDark.value = media.matches; };
media.addEventListener('change', updateSystem);
onBeforeUnmount(() => media.removeEventListener('change', updateSystem));
const dark = computed(() => themeChoice.value === 'dark' || (themeChoice.value === 'system' && systemDark.value));
watch([dark, themeChoice], () => { document.documentElement.dataset.theme = dark.value ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
const canWrite = computed(() => role.value === 'platformAdmin' || role.value === 'tenantAdmin');
const draftFilters = ref(initialList()), filters = ref(initialList()), rows = ref<Product[]>([]), total = ref(0), listLoading = ref(true);
const selectedProducts = ref<string[]>([]);
const visibleSelected = computed(() => rows.value.filter(product => selectedProducts.value.includes(product.id)));
function toggleProduct(id: string) { selectedProducts.value = selectedProducts.value.includes(id) ? selectedProducts.value.filter(value => value !== id) : [...selectedProducts.value, id]; }
const selectedId = ref<string | null>(null), detail = ref<Product | null>(null), tab = ref<Tab>('basic');
const devicePage = ref(1), deviceRows = ref<Device[]>([]), deviceTotal = ref(0), deviceLoading = ref(false), deviceError = ref('');
const base = ref<ProductInput>(emptyProduct('all'));
const access = ref<AccessConfig>(defaultAccessConfig('MQTT'));
const model = ref<ThingModelItem>(emptyItem()), modelOriginal = ref<ThingModelItem>(emptyItem()), jsonMode = ref(false), jsonText = ref(JSON.stringify(emptyItem(), null, 2));
const modelJsonInput = ref<HTMLTextAreaElement | null>(null);
const rule = ref<DpRule>(emptyRule('')), ruleOriginal = ref<DpRule>(emptyRule('')), raw = ref('850'), conversion = ref<Conversion | null>(null);
const enumText = ref('[]');
const message = ref(''), fieldErrors = ref<Record<string, string>>({}), pending = ref<string | null>(null), impact = ref<'base' | 'model' | 'remove' | null>(null), typePending = ref<DataType | null>(null), removeId = ref(''), reload = ref(0);
const capacityNote = ref('');
const modalKind = computed(() => pending.value ? 'pending' : impact.value ? 'impact' : typePending.value ? 'type' : null);
let modalTrigger: HTMLElement | null = null;
watch(modalKind, async (current, previous) => {
  if (current && !previous) modalTrigger = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  await nextTick();
  if (current) document.querySelector<HTMLElement>('.product-modal[role="dialog"]')?.focus();
  else if (previous === 'type') { document.querySelector<HTMLElement>('[aria-label="数据类型"]')?.focus(); modalTrigger = null; }
  else if (modalTrigger?.isConnected) { modalTrigger.focus(); modalTrigger = null; }
}, { flush: 'post' });
const onModalKeydown = (event: KeyboardEvent) => {
  const kind = modalKind.value;
  const dialog = document.querySelector<HTMLElement>('.product-modal[role="dialog"]');
  if (!kind || !dialog) return;
  if (event.key === 'Escape') { event.preventDefault(); if (kind === 'pending') pending.value = null; else if (kind === 'impact') { impact.value = null; removeId.value = ''; } else typePending.value = null; return; }
  if (event.key !== 'Tab') return;
  const buttons = Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled])'));
  if (!buttons.length) return;
  const first = buttons[0], last = buttons[buttons.length - 1];
  if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && (document.activeElement === last || document.activeElement === dialog)) { event.preventDefault(); first.focus(); }
};
window.addEventListener('keydown', onModalKeydown);
onBeforeUnmount(() => window.removeEventListener('keydown', onModalKeydown));
const dirty = computed(() => !!selectedId.value && (tab.value === 'basic' ? JSON.stringify(base.value) !== JSON.stringify(detail.value ? productInput(detail.value) : emptyProduct(filters.value.tenantId)) : tab.value === 'access' ? !!detail.value && JSON.stringify(access.value) !== JSON.stringify(detail.value.accessConfig) : tab.value === 'model' ? (jsonMode.value ? jsonText.value !== JSON.stringify(modelOriginal.value, null, 2) : JSON.stringify(model.value) !== JSON.stringify(modelOriginal.value)) : tab.value === 'dp' ? JSON.stringify(rule.value) !== JSON.stringify(ruleOriginal.value) || enumText.value !== JSON.stringify(ruleOriginal.value.enumMap) : false));
const identifierIssue = computed(() => tab.value === 'model' && !jsonMode.value && detail.value ? modelIdentifierError(model.value.identifier, model.value.id, detail.value.model) : null);
const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty.value) event.preventDefault(); };
window.addEventListener('beforeunload', beforeUnload);
onBeforeUnmount(() => window.removeEventListener('beforeunload', beforeUnload));
const context = (): Context => ({ actorId: 'usr_202609_001', role: role.value, tenantId: role.value === 'platformAdmin' ? 'all' : 'ten_202609_001', seed: 42, scenario: scenario.value });
watch([selectedId, () => base.value.tenantId, role, scenario], async ([id, tenantId], _, onCleanup) => {
  if (id !== 'new') { capacityNote.value = ''; return; }
  let active = true; onCleanup(() => { active = false; }); capacityNote.value = '正在查询产品配额…';
  const result = await tenants.checkCapacity(context(), tenantId, 'products');
  if (!active) return;
  capacityNote.value = 'error' in result ? result.error.message : `产品配额已用 ${result.data.used}/${result.data.limit}${(result.data.used + 1) / result.data.limit * 100 >= result.data.warningAt ? `；保存后达到 ${result.data.warningAt}% 预警阈值` : ''}`;
});
let listRequest = 0, detailRequest = 0;
let deviceRequest = 0;
watch([tab, detail, role, scenario, devicePage, reload], async () => {
  const current = ++deviceRequest;
  if (tab.value !== 'devices' || !detail.value) { deviceRows.value = []; deviceTotal.value = 0; deviceError.value = ''; return; }
  deviceLoading.value = true; deviceError.value = ''; deviceRows.value = [];
  const response = await devices.list(context(), { tenantId: detail.value.tenantId, productId: detail.value.id, seed: 42, page: devicePage.value, pageSize: 10, sortBy: 'name', sortDirection: 'asc' });
  if (current !== deviceRequest) return;
  if ('error' in response) { deviceRows.value = []; deviceTotal.value = 0; deviceError.value = response.error.message; }
  else { deviceRows.value = response.data.items; deviceTotal.value = response.data.total; }
  deviceLoading.value = false;
});
watch([filters, role, scenario, reload], async () => { const current = ++listRequest; listLoading.value = true; selectedProducts.value = []; const query = filters.value; const response = await products.list(context(), { tenantId: query.tenantId, keyword: query.keyword || undefined, category: query.category || undefined, status: query.status as ProductStatus || undefined, page: query.page, pageSize: query.pageSize, seed: 42 }); if (current !== listRequest) return; if ('error' in response) { message.value = response.error.message; rows.value = []; total.value = 0; if (response.error.code === 'FORBIDDEN') clearProtectedView(); } else { rows.value = response.data.items; total.value = response.data.total; } listLoading.value = false; }, { immediate: true });
watch([selectedId, role, scenario, reload], async () => { const current = ++detailRequest; if (!selectedId.value || selectedId.value === 'new') return; const response = await products.get(context(), selectedId.value); if (current !== detailRequest) return; if ('error' in response) { message.value = response.error.message; selectedId.value = null; detail.value = null; } else { detail.value = response.data; base.value = productInput(response.data); access.value = copy(response.data.accessConfig); fieldErrors.value = {}; } });
function clearProtectedView() { rows.value = []; total.value = 0; selectedProducts.value = []; selectedId.value = null; detail.value = null; pending.value = null; impact.value = null; typePending.value = null; detailRequest++; }
watch(scenario, value => { if (value === 'forbidden') clearProtectedView(); }, { flush: 'sync' });
function showResult(response: { error: { message: string; fieldErrors?: Record<string, string> } } | { data: Product }, onSuccess?: (product: Product) => void) { if ('error' in response) { message.value = response.error.message; fieldErrors.value = response.error.fieldErrors ?? {}; return false; } detail.value = response.data; base.value = productInput(response.data); access.value = copy(response.data.accessConfig); message.value = '已保存'; fieldErrors.value = {}; reload.value++; onSuccess?.(response.data); return true; }
async function saveBase(confirmImpact = false) { const response = await products.save(context(), base.value, detail.value?.id, detail.value?.version, confirmImpact); if ('error' in response && response.error.fieldErrors?.confirmImpact) { impact.value = 'base'; message.value = response.error.message; return false; } return showResult(response, product => { selectedId.value = product.id; impact.value = null; }); }
async function saveAccess() { return detail.value ? showResult(await products.saveAccessConfig(context(), detail.value.id, { ...access.value, heartbeatSeconds: Number(access.value.heartbeatSeconds) }, detail.value.version)) : false; }
function parseModel() { const parsed = parseJsonObject<ThingModelItem>(jsonText.value); if (parsed.error) { message.value = parsed.error.message; fieldErrors.value = { modelJson: parsed.error.message }; modelJsonInput.value?.focus(); modelJsonInput.value?.setSelectionRange(parsed.error.offset, parsed.error.offset); return null; } model.value = parsed.value; fieldErrors.value = {}; message.value = ''; return parsed.value; }
async function saveModel(confirmImpact = false) { if (!detail.value) return false; const current = jsonMode.value ? parseModel() : model.value; if (!current) return false; const next = { ...current }; const response = await products.saveModel(context(), detail.value.id, next, detail.value.version, confirmImpact); if ('error' in response && response.error.fieldErrors?.confirmImpact) { impact.value = 'model'; message.value = response.error.message; return false; } return showResult(response, product => { const saved = product.model.find(item => item.id === next.id || (!next.id && item.identifier === next.identifier)) ?? next; model.value = saved; modelOriginal.value = saved; jsonText.value = JSON.stringify(saved, null, 2); impact.value = null; }); }
async function removeModel(confirmed = false) { if (!detail.value) return false; const response = await products.removeModel(context(), detail.value.id, removeId.value, detail.value.version, confirmed); if ('error' in response && response.error.fieldErrors?.confirmImpact) { impact.value = 'remove'; message.value = response.error.message; return false; } return showResult(response, () => { impact.value = null; removeId.value = ''; model.value = emptyItem(); modelOriginal.value = emptyItem(); }); }
function parseEnumText(): DpRule['enumMap'] | null { try { const parsed: unknown = JSON.parse(enumText.value); if (!Array.isArray(parsed)) throw new Error('映射必须是数组'); const { enumMap, ...rest } = fieldErrors.value; void enumMap; fieldErrors.value = rest; return parsed as DpRule['enumMap']; } catch { fieldErrors.value = { ...fieldErrors.value, enumMap: '枚举映射须为有效 JSON 数组' }; conversion.value = null; return null; } }
async function saveRule() { if (!detail.value) return false; const enumMap = parseEnumText(); if (!enumMap) return false; const next = { ...rule.value, enumMap, id: rule.value.id || `dp_${rule.value.itemId}` }; return showResult(await products.saveDpRule(context(), detail.value.id, next, detail.value.version), () => { rule.value = next; ruleOriginal.value = next; enumText.value = JSON.stringify(next.enumMap); }); }
async function saveCurrent() { return tab.value === 'basic' ? saveBase() : tab.value === 'access' ? saveAccess() : tab.value === 'model' ? saveModel() : tab.value === 'dp' ? saveRule() : true; }
function open(id: string | null) { if (dirty.value) { pending.value = id ?? 'close'; return; } selectedId.value = id; detail.value = null; message.value = ''; fieldErrors.value = {}; tab.value = 'basic'; if (id === 'new') { base.value = emptyProduct(filters.value.tenantId); access.value = defaultAccessConfig('MQTT'); } }
function discard() { const target = pending.value; pending.value = null; message.value = ''; fieldErrors.value = {}; if (target?.startsWith('tab:')) { base.value = detail.value ? productInput(detail.value) : emptyProduct(filters.value.tenantId); access.value = copy(detail.value?.accessConfig ?? defaultAccessConfig('MQTT')); model.value = copy(modelOriginal.value); jsonText.value = JSON.stringify(modelOriginal.value, null, 2); jsonMode.value = false; rule.value = copy(ruleOriginal.value); enumText.value = JSON.stringify(ruleOriginal.value.enumMap); const next = target.slice(4) as Tab; if (next === 'dp' && detail.value?.model.length) editRule(detail.value.model[0].id); else if (next === 'model') editModel(); else tab.value = next; return; } selectedId.value = target === 'close' ? null : target; detail.value = null; tab.value = 'basic'; if (target === 'new') { base.value = emptyProduct(filters.value.tenantId); tab.value = 'basic'; } }
function editModel(item?: ThingModelItem) { const next = item ? copy(item) : emptyItem(); model.value = next; modelOriginal.value = copy(next); jsonText.value = JSON.stringify(next, null, 2); jsonMode.value = false; conversion.value = null; fieldErrors.value = {}; tab.value = 'model'; }
function changeModelType(next: DataType) {
  if (next === model.value.dataType) return;
  const numeric = next === 'float' || next === 'int';
  const incompatible = numeric ? !!model.value.enumValues?.length : !!model.value.unit?.trim() || model.value.min !== undefined || model.value.max !== undefined;
  if (incompatible) typePending.value = next;
  else model.value = { ...model.value, dataType: next };
}
function confirmModelType() {
  if (!typePending.value) return;
  const { unit, min, max, enumValues, ...compatible } = model.value;
  const next = typePending.value;
  model.value = next === 'float' || next === 'int' ? { ...compatible, dataType: next, unit: unit ?? '', min: min ?? 0, max: max ?? 100 }
    : next === 'enum' ? { ...compatible, dataType: next, enumValues: enumValues ?? [] } : { ...compatible, dataType: next };
  typePending.value = null;
}
function editRule(itemId: string) { const next = detail.value?.dpRules.find(candidate => candidate.itemId === itemId) ?? emptyRule(itemId); rule.value = copy(next); ruleOriginal.value = copy(next); enumText.value = JSON.stringify(next.enumMap); conversion.value = null; fieldErrors.value = {}; tab.value = 'dp'; }
async function testRule() { if (!detail.value) return; const enumMap = parseEnumText(); if (!enumMap) return; const response = await products.testDpRule(context(), detail.value.id, { ...rule.value, enumMap }, raw.value); if ('error' in response) { message.value = response.error.message; fieldErrors.value = response.error.fieldErrors ?? {}; conversion.value = null; } else { conversion.value = response.data; message.value = ''; fieldErrors.value = {}; } }
function chooseTab(id: Tab) { if (dirty.value) { pending.value = `tab:${id}`; return; } if (id === 'dp' && detail.value?.model.length) editRule(detail.value.model[0].id); else if (id === 'model') editModel(); else { if (id === 'devices') devicePage.value = 1; tab.value = id; } }
function changeRole(value: Role) { clearProtectedView(); role.value = value; const tenantId = value === 'platformAdmin' ? 'all' : 'ten_202609_001'; draftFilters.value = { ...draftFilters.value, tenantId, page: 1 }; filters.value = { ...filters.value, tenantId, page: 1 }; }
function apply() { filters.value = { ...draftFilters.value, page: 1 }; }
function reset() { const next = initialList(); if (role.value !== 'platformAdmin') next.tenantId = 'ten_202609_001'; draftFilters.value = next; filters.value = next; }
function setPageSize(value: number) { filters.value = { ...filters.value, page: 1, pageSize: value }; draftFilters.value = { ...draftFilters.value, page: 1, pageSize: value }; }
function refresh() { message.value = ''; reload.value++; }
</script>
<template>
  <div class="atlas-dashboard atlas-products"><aside class="atlas-sidebar" aria-label="主导航"><div class="atlas-brand">IoT <strong>Atlas</strong></div><nav><a href="/dashboard">◇ 数据大盘</a><a href="/geography">◇ 全球节点</a><a class="active" href="/products" aria-current="page">▣ 产品与物模型</a><a href="/devices">◇ 设备中心</a><a href="/rules">◇ 规则引擎</a><a href="/firmware">◇ 固件与 OTA</a><a href="/tenants">◇ 租户管理</a><a href="/labs">◇ 实验室</a><a href="/delivery">◇ 交付看板</a></nav><a class="diagnostic-link" href="/">诊断页</a></aside>
    <main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 产品与物模型</small><h1>产品与物模型</h1><p>配置产品能力、物模型与 DP 转换；仅模拟保存与校验。</p></div><div class="header-actions"><label>主题<select v-model="themeChoice" aria-label="主题"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>演示身份<select :value="role" aria-label="演示身份" @change="changeRole(($event.target as HTMLSelectElement).value as Role)"><option value="platformAdmin">平台管理员</option><option value="tenantAdmin">租户管理员</option><option value="operator">运维工程师</option><option value="viewer">数据观察员</option></select></label></div></header>
      <ElCard class="product-filters" role="region" aria-label="产品筛选"><div class="product-filter-grid"><label>搜索<input v-model="draftFilters.keyword" aria-label="搜索产品" placeholder="名称或 Product Key"></label><label>租户<select v-model="draftFilters.tenantId" aria-label="租户" :disabled="role !== 'platformAdmin'"><option v-for="(name, id) in tenantNames" :key="id" :value="id">{{ name }}</option></select></label><label>类别<select v-model="draftFilters.category" aria-label="类别"><option value="">全部类别</option><option v-for="name in ['工业传感器', '能源设备', '水务设备', '安防设备']" :key="name">{{ name }}</option></select></label><label>状态<select v-model="draftFilters.status" aria-label="状态"><option value="">全部状态</option><option v-for="(name, id) in statusNames" :key="id" :value="id">{{ name }}</option></select></label><div class="product-filter-actions"><ElButton type="primary" @click="apply">查询</ElButton><ElButton @click="reset">重置</ElButton></div></div><details class="scenario-control"><summary>演示状态</summary><label>Mock 场景<select v-model="scenario" aria-label="Mock 场景"><option value="normal">正常</option><option value="slow">缓慢</option><option value="offline">服务离线</option><option value="forbidden">无权限</option></select></label></details></ElCard>
      <div class="dashboard-feedback" aria-live="polite"><span v-if="listLoading" role="status">产品加载中…</span><span v-if="message" role="alert">{{ message }} <ElButton size="small" @click="refresh">刷新</ElButton></span></div>
      <ElCard class="product-list" role="region"><div class="product-list-head"><h2>产品列表 <small>共 {{ total }} 条</small></h2><ElButton :disabled="!visibleSelected.length" @click="downloadProductCsv(visibleSelected)">导出已选（{{ visibleSelected.length }}）</ElButton><ElButton v-if="canWrite" type="primary" @click="open('new')">新建产品</ElButton></div><div class="product-table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="选择当前页产品" :checked="!!rows.length && visibleSelected.length === rows.length" @change="selectedProducts = ($event.target as HTMLInputElement).checked ? rows.map(product => product.id) : []"></th><th>产品名称</th><th>Product Key</th><th>类别</th><th>协议</th><th>设备数</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="product in rows" :key="product.id"><td><input type="checkbox" :aria-label="`选择产品 ${product.name}`" :checked="selectedProducts.includes(product.id)" @change="toggleProduct(product.id)"></td><td><button @click="open(product.id)">{{ product.name }}</button></td><td>{{ product.productKey }}</td><td>{{ product.category }}</td><td>{{ product.protocol }}</td><td>{{ number(product.deviceCount) }}</td><td>{{ statusNames[product.status] }}</td><td>{{ new Date(product.updatedAt).toLocaleDateString('zh-CN') }}</td></tr></tbody></table><p v-if="!listLoading && !rows.length">当前筛选范围没有产品。</p></div><div class="product-pager"><label>每页<select :value="filters.pageSize" aria-label="每页条数" @change="setPageSize(Number(($event.target as HTMLSelectElement).value))"><option :value="2">2</option><option :value="10">10</option><option :value="20">20</option></select></label><ElButton :disabled="filters.page <= 1" @click="filters = { ...filters, page: filters.page - 1 }">上一页</ElButton><span>{{ filters.page }} / {{ Math.max(1, Math.ceil(total / filters.pageSize)) }}</span><ElButton :disabled="filters.page * filters.pageSize >= total" @click="filters = { ...filters, page: filters.page + 1 }">下一页</ElButton></div></ElCard>
    </main><aside v-if="selectedId" class="product-drawer" role="dialog" aria-modal="false" aria-label="产品详情"><div class="drawer-head"><h2>{{ selectedId === 'new' ? '新建产品' : detail?.name ?? '产品加载中' }}</h2><button aria-label="关闭详情" @click="open(null)">×</button></div><p v-if="selectedId === 'new'" role="status">{{ capacityNote }}</p><div class="product-tabs" role="tablist" aria-label="产品详情页签"><button v-for="entry in tabs" :key="entry.id" role="tab" :aria-selected="tab === entry.id" :disabled="selectedId !== 'new' && !detail" @click="chooseTab(entry.id)">{{ entry.name }}</button></div><p v-if="dirty" class="unsaved" role="status">● 未保存变更</p>
      <div v-if="tab === 'basic'" class="product-form" role="tabpanel"><label>租户<select v-model="base.tenantId" aria-label="产品租户" :disabled="!!detail || !canWrite"><option v-for="(name, id) in tenantNames" v-show="id !== 'all'" :key="id" :value="id">{{ name }}</option></select></label><label>产品名称<input v-model="base.name" aria-label="产品名称" :disabled="!canWrite"></label><label>Product Key<input v-model="base.productKey" aria-label="Product Key" :disabled="!canWrite"></label><label>类别<select v-model="base.category" aria-label="产品类别" :disabled="!canWrite"><option v-for="name in ['工业传感器', '能源设备', '水务设备', '安防设备']" :key="name">{{ name }}</option></select></label><label>接入协议<select v-model="base.protocol" aria-label="接入协议" :disabled="!canWrite"><option>MQTT</option><option>CoAP</option><option>HTTP</option></select></label><label>产品状态<select v-model="base.status" aria-label="产品状态" :disabled="!canWrite"><option v-for="(name, id) in statusNames" :key="id" :value="id">{{ name }}</option></select></label><ElButton v-if="canWrite" type="primary" @click="saveBase()">保存产品</ElButton></div>
      <div v-if="tab === 'access'" class="product-form" role="tabpanel"><template v-if="detail"><p>协议：{{ detail.protocol }}。以下为本地 Mock 接入元数据，不包含真实凭据或服务地址。</p><label>{{ detail.protocol === 'MQTT' ? '上行 Topic' : '上行资源路径' }}<input v-model="access.uplinkPath" aria-label="上行路径" :disabled="!canWrite"></label><label>{{ detail.protocol === 'MQTT' ? '下行 Topic' : '下行资源路径' }}<input v-model="access.downlinkPath" aria-label="下行路径" :disabled="!canWrite"></label><label>报文格式<select v-model="access.payloadFormat" aria-label="报文格式" :disabled="!canWrite"><option>JSON</option><option>Binary</option></select></label><label>心跳间隔（秒）<input v-model.number="access.heartbeatSeconds" aria-label="心跳间隔" type="number" min="10" max="3600" :disabled="!canWrite"></label><ElButton v-if="canWrite" type="primary" @click="saveAccess">保存接入配置</ElButton></template><p v-else>请先保存产品，再配置接入路径。</p></div>
      <div v-if="tab === 'model'" role="tabpanel"><div class="product-section-head"><h3>物模型</h3><ElButton v-if="canWrite && detail" @click="editModel()">添加模型项</ElButton></div><table><thead><tr><th>名称</th><th>标识</th><th>类型</th><th>操作</th></tr></thead><tbody><tr v-for="entry in detail?.model" :key="entry.id"><td>{{ entry.name }}</td><td>{{ entry.identifier }}</td><td>{{ kindNames[entry.kind] }} · {{ entry.dataType }}</td><td><button @click="editModel(entry)">编辑</button><button v-if="canWrite" @click="removeId = entry.id; removeModel()">删除</button></td></tr></tbody></table><p v-if="detail?.model.length === 0">暂无物模型项。</p><div v-if="detail" class="model-editor"><h3>模型项编辑</h3><div class="model-mode"><ElButton @click="() => { if (jsonMode && !parseModel()) return; jsonMode = false; }">表单</ElButton><ElButton @click="jsonText = JSON.stringify(model, null, 2); jsonMode = true">JSON</ElButton></div><label v-if="jsonMode">JSON 草稿<textarea ref="modelJsonInput" v-model="jsonText" aria-label="物模型 JSON" :disabled="!canWrite" rows="12" /></label><div v-else class="product-form"><label>类型<select v-model="model.kind" aria-label="模型类型" :disabled="!canWrite"><option value="property">属性</option><option value="event">事件</option><option value="service">服务</option></select></label><label>标识符<input v-model="model.identifier" aria-label="模型标识符" :disabled="!canWrite"></label><p v-if="identifierIssue" class="product-inline-error" role="alert">{{ identifierIssue }}</p><label>名称<input v-model="model.name" aria-label="模型名称" :disabled="!canWrite"></label><label>数据类型<select :value="model.dataType" aria-label="数据类型" :disabled="!canWrite" @change="changeModelType(($event.target as HTMLSelectElement).value as DataType)"><option value="float">float</option><option value="int">int</option><option value="enum">enum</option><option value="bool">bool</option><option value="string">string</option></select></label><label>读写权限<select v-model="model.accessMode" aria-label="读写权限" :disabled="!canWrite"><option v-for="(name, id) in accessNames" :key="id" :value="id">{{ name }}</option></select></label><label>单位<input v-model="model.unit" aria-label="单位" :disabled="!canWrite"></label><label>最小值<input v-model.number="model.min" aria-label="最小值" type="number" :disabled="!canWrite"></label><label>最大值<input v-model.number="model.max" aria-label="最大值" type="number" :disabled="!canWrite"></label><label>枚举值（逗号分隔）<input aria-label="枚举值" :value="model.enumValues?.join(',') ?? ''" :disabled="!canWrite" @input="model.enumValues = ($event.target as HTMLInputElement).value.split(',').filter(Boolean)"></label></div><details><summary>JSON 预览</summary><pre>{{ jsonMode ? jsonText : JSON.stringify(model, null, 2) }}</pre></details><ElButton v-if="canWrite" type="primary" @click="saveModel()">保存模型项</ElButton></div></div>
      <div v-if="tab === 'dp'" role="tabpanel"><h3>DP 转换规则</h3><template v-if="detail?.model.length"><label class="product-inline">目标物模型项<select :value="rule.itemId || detail.model[0].id" aria-label="目标物模型项" @change="editRule(($event.target as HTMLSelectElement).value)"><option v-for="entry in detail.model" :key="entry.id" :value="entry.id">{{ entry.name }}（{{ entry.identifier }}）</option></select></label><div class="product-form"><label>原始类型<select v-model="rule.rawType" aria-label="原始类型" :disabled="!canWrite"><option>int16</option><option>float</option><option>string</option></select></label><label>倍率<input v-model.number="rule.scale" aria-label="倍率" type="number" :disabled="!canWrite"></label><label>偏移<input v-model.number="rule.offset" aria-label="偏移" type="number" :disabled="!canWrite"></label><label>精度<input v-model.number="rule.precision" aria-label="精度" type="number" :disabled="!canWrite"></label><label>表达式<input v-model="rule.expression" aria-label="表达式" :disabled="!canWrite"></label><label>阈值下限<input aria-label="阈值下限" type="number" :value="rule.threshold?.min ?? ''" :disabled="!canWrite" @input="rule.threshold = { min: Number(($event.target as HTMLInputElement).value), max: rule.threshold?.max ?? 100 }"></label><label>阈值上限<input aria-label="阈值上限" type="number" :value="rule.threshold?.max ?? ''" :disabled="!canWrite" @input="rule.threshold = { min: rule.threshold?.min ?? 0, max: Number(($event.target as HTMLInputElement).value) }"></label><label>枚举映射（JSON）<textarea aria-label="枚举映射" v-model="enumText" :disabled="!canWrite" rows="3" @input="conversion = null"></textarea></label></div><div class="dp-run"><label>原始样例<input v-model="raw" aria-label="原始样例"></label><ElButton @click="testRule">运行转换测试</ElButton><ElButton v-if="canWrite" type="primary" @click="saveRule">保存 DP 规则</ElButton></div><div v-if="conversion" class="conversion" role="status"><h3>转换结果：{{ conversion.valid ? conversion.value : conversion.error }}</h3><ol><li v-for="(step, index) in conversion.steps" :key="index">{{ step.label }}：{{ step.input }} → {{ step.output }}</li></ol></div></template><p v-else>请先配置物模型项。</p></div>
      <div v-if="tab === 'devices'" role="tabpanel"><h3>关联设备</h3><template v-if="detail"><p>共 {{ number(deviceTotal) }} 台设备关联此产品。关键模型变更需确认影响。</p><p v-if="deviceLoading" role="status">关联设备加载中…</p><p v-if="deviceError" role="alert">{{ deviceError }} <button @click="reload++">重试</button></p><p v-if="!deviceLoading && !deviceError && !deviceRows.length">当前产品没有关联设备。</p><ul class="product-device-list"><li v-for="device in deviceRows" :key="device.id"><a :href="`/devices?device=${encodeURIComponent(device.id)}`">{{ device.name }} · {{ device.id }}</a><span>{{ deviceStatusNames[device.status] }} · {{ device.region }}</span></li></ul><div v-if="deviceTotal > 10" class="product-device-pager"><button :disabled="devicePage <= 1" @click="devicePage--">上一页</button><span>{{ devicePage }} / {{ Math.ceil(deviceTotal / 10) }}</span><button :disabled="devicePage * 10 >= deviceTotal" @click="devicePage++">下一页</button></div></template><p v-else>先保存产品以关联设备。</p></div><div v-if="Object.keys(fieldErrors).length" class="product-errors" role="alert"><h3>校验摘要</h3><ul><li v-for="(error, field) in fieldErrors" :key="field">{{ field }}：{{ error }}</li></ul></div>
    </aside>
    <div v-if="pending" class="product-modal-backdrop"><div class="product-modal" role="dialog" aria-modal="true" tabindex="-1" aria-label="未保存变更"><h2>未保存变更</h2><p>当前编辑内容尚未保存。请选择后继续。</p><div><ElButton type="primary" @click="saveCurrent().then(success => { if (success) discard(); })">保存并离开</ElButton><ElButton @click="discard">放弃更改</ElButton><ElButton @click="pending = null">取消</ElButton></div></div></div>
    <div v-if="typePending" class="product-modal-backdrop"><div class="product-modal" role="dialog" aria-modal="true" tabindex="-1" aria-label="数据类型切换确认"><h2>切换数据类型</h2><p>不兼容的单位、数值范围或枚举值将被清除。</p><div><ElButton type="primary" @click="confirmModelType">确认清除并切换</ElButton><ElButton @click="typePending = null">取消</ElButton></div></div></div>
    <div v-if="impact" class="product-modal-backdrop"><div class="product-modal" role="dialog" aria-modal="true" tabindex="-1" aria-label="影响确认"><h2>影响确认</h2><p>{{ message }}</p><p>关联设备、规则与 OTA 可能受影响。</p><div><ElButton type="primary" @click="impact === 'base' ? saveBase(true) : impact === 'model' ? saveModel(true) : removeModel(true)">确认影响并保存</ElButton><ElButton @click="impact = null; removeId = ''">取消</ElButton></div></div></div>
  </div>
</template>
